<?php
namespace App\Tests\Runtime;
use App\Entity\{BuilderEntity,BuilderField,RuntimeTransaction,RuntimeTransactionLog};
use App\Repository\BuilderEntityRepository;
use App\Runtime\{RuntimeApiEntityActionService,RuntimeExternalJsonClient,RuntimeTransactionService,RuntimeExecutionContext,RuntimeEntityDefinitionResolver,RuntimeEnvironmentIdentityResolver,PermissionResolver,RuntimeHttpException};
use Doctrine\ORM\EntityManagerInterface;
use PHPUnit\Framework\TestCase;
require_once __DIR__.'/RuntimePurchaseItemAuditTest.php';
final class RuntimePurchaseItemTransportTest extends TestCase
{
    private function service(string $op,array $body,array &$sent,array &$logs,bool $badPresentationMapping=false,bool $badReadonly=false): RuntimeApiEntityActionService
    {
        $d=RuntimePurchaseItemAuditTest::definition();$endpoint=RuntimePurchaseItemAuditTest::endpoint($op);
        $api=['responseContract'=>'sursum-programs','authHeaders'=>[],'listEndpoint'=>$endpoint,'listResponse'=>['itemsPath'=>'data'],$op.'Endpoint'=>$endpoint,$op.'Response'=>['itemPath'=>'data']];
        if($op==='get'){$api['detailEndpoint']=$endpoint;$api['detailResponse']=['itemPath'=>'data'];}
        $entity=(new BuilderEntity())->setCode($d['entityCode'])->setEntityType('api')->setMetadata(['apiSource'=>$api,'apiBinding'=>$d['apiBinding']]);
        foreach(RuntimePurchaseItemAuditTest::data() as $name=>$v){$type=match($name){'item_proc_compra_id','qt_dias_producao','coloracao_id','formato_amostra_id','ind_producao_no_prazo','ind_relat_semanal_producao','ind_qualid_emb','ind_laudo_antes_embarque','ind_prod_conf_pi','ind_rec_amostra_antes_emb','ind_qt_conf_proforma','ind_tamanho_pecas_correto','qt_dias_calc_so_ld','ind_distr_custo','item_estacao'=>'integer','qt_comprada','vl_custo_dolar','vl_base_tributacao','vl_cubagem','vl_negociado','qt_alocada','qt_saldo','calc_gm'=>'decimal','log_aprov_so_ld','log_mostruario'=>'boolean','proc_compra_id','empresa_id','fornecedor_id','qt_container','cod_situacao','qt_dias_translado'=>'integer','cotacao_prevista'=>'decimal','dt_registro','dt_limite'=>'date','log_facilid_contato_fornec','log_considerar_previsao'=>'boolean',default=>'string'};$readonly=in_array($name,['item_proc_compra_id','proc_compra_id','row_stamp','qt_alocada','qt_saldo','calc_gm'],true);
            if($badReadonly && in_array($name,['proc_compra_id','qt_alocada','qt_saldo','calc_gm'],true))$readonly=false;
            $apiField=['writePath'=>$readonly?$name:'values.'.$name];if($badPresentationMapping&&$name==='observacao')$apiField['collection']='integer';
            $entity->addField((new BuilderField())->setCode($name)->setLabel($name)->setRequired(in_array($name,['descricao','unid_medida'],true))->setLength($name==='descricao'?100:null)->setDataType($type)->setPrimaryKey($name==='item_proc_compra_id')->setOptions(['readonly'=>$readonly,'api'=>$apiField]));}
        $repo=$this->createStub(BuilderEntityRepository::class);$repo->method('findOneBy')->willReturn($entity);
        $manager=$this->createStub(EntityManagerInterface::class);$manager->method('persist')->willReturnCallback(static function($item)use(&$logs){if($item instanceof RuntimeTransactionLog)$logs[]=$item;});
        $p=$this->createStub(PermissionResolver::class);$p->method('hasPermission')->willReturn(true);
        $tx=new RuntimeTransactionService($manager,$p,new RuntimeExecutionContext(),$this->createStub(RuntimeEntityDefinitionResolver::class),$this->createStub(RuntimeEnvironmentIdentityResolver::class));
        $current=(new RuntimeTransaction())->setTenantId('a')->setRequestContext(['actor'=>['source'=>'authenticated-session','version'=>1,'username'=>'real-user']]);(new \ReflectionProperty($tx,'current'))->setValue($tx,$current);
        $client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($url,$method,$headers,$request)use($body,&$sent){$sent[]=$request;return ['status'=>200,'body'=>$body];});
        return new RuntimeApiEntityActionService($repo,$tx,$client,$p);
    }
    private function invoke(RuntimeApiEntityActionService $s,string $op,array $record,mixed $id=null): array
    { return $s->handle('ciw.proc-compra-itens',$op,['entityCode'=>'proc_compra_itens_progress','operation'=>$op],['context'=>['proc_compra_id'=>17],'record'=>$record]+($id===null?[]:['id'=>$id])); }
    public function testClosedTransportForAllMutations(): void {
        foreach(['create','update','delete']as $op){$sent=[];$logs=[];$s=$this->service($op,RuntimePurchaseItemAuditTest::body($op),$sent,$logs);$r=RuntimePurchaseItemAuditTest::data();if($op==='create')unset($r['item_proc_compra_id'],$r['row_stamp']);$this->invoke($s,$op,$r,$op==='create'?null:'11');self::assertCount(1,$sent);self::assertSame(17,$sent[0]['proc_compra_id']);if($op==='create'){self::assertArrayNotHasKey('row_stamp',$sent[0]);}else{self::assertSame(11,$sent[0]['id']);self::assertSame(str_repeat('A',64),$sent[0]['row_stamp']);}if($op==='delete')self::assertArrayNotHasKey('values',$sent[0]);else foreach(['item_proc_compra_id','proc_compra_id','row_stamp','qt_alocada','qt_saldo','calc_gm']as $key)self::assertArrayNotHasKey($key,$sent[0]['values']);$confirmed=array_values(array_filter($logs,fn($l)=>$l->getMetadata()['audit']['available']??false));self::assertCount(1,$confirmed);}
    }
    public function testForgedIdentityStampUnknownAndParentNeverReachWriter():void {foreach(['missing-stamp','alias','parent','unknown','create-id','create-stamp']as $case){$sent=[];$logs=[];$op=str_starts_with($case,'create')?'create':'update';$r=RuntimePurchaseItemAuditTest::data();if($case==='missing-stamp')unset($r['row_stamp']);if($case==='alias')$r['id']=12;if($case==='parent')$r['proc_compra_id']=18;if($case==='unknown')$r['scope']='free';if($case==='create-id')unset($r['row_stamp']);if($case==='create-stamp')unset($r['item_proc_compra_id']);$s=$this->service($op,RuntimePurchaseItemAuditTest::body($op),$sent,$logs);try{$this->invoke($s,$op,$r,$op==='create'?null:11);self::fail($case);}catch(RuntimeHttpException $e){self::assertContains($e->getStatusCode(),[422,502]);}self::assertSame([],$sent,$case);}}
    public function testCommittedMissingOrMalformedImagesWarnOnceWithoutReplaying(): void
    {
        foreach(['missing','actor','data']as $case){$body=RuntimePurchaseItemAuditTest::body('create');switch($case){case 'missing':unset($body['audit']);break;case 'actor':$body['audit']['actor']['login']='spoof';break;case 'data':$body['data']='invalid';break;}$sent=[];$logs=[];$s=$this->service('create',$body,$sent,$logs);$record=RuntimePurchaseItemAuditTest::row();unset($record['item_proc_compra_id']);$result=$this->invoke($s,'create',$record);self::assertCount(1,$sent);self::assertSame('warning',$result['effects'][0]['type']);foreach($logs as $log){self::assertFalse($log->getMetadata()['audit']['available']??false);self::assertSame([],$log->getBeforeData());self::assertSame([],$log->getAfterData());}}
    }
    public function testCommittedPresentationFailureNeverLosesTheValidatedStampOrRepeatsTheWriter(): void
    {
        foreach(['create','update']as $op){$sent=[];$logs=[];$s=$this->service($op,RuntimePurchaseItemAuditTest::body($op),$sent,$logs,true);$record=RuntimePurchaseItemAuditTest::data();unset($record['observacao']);if($op==='create')unset($record['item_proc_compra_id'],$record['row_stamp']);$result=$this->invoke($s,$op,$record,$op==='update'?'11':null);self::assertCount(1,$sent);self::assertSame(str_repeat('A',64),$result['row_stamp']);self::assertSame('',$result['observacao']);}
    }
 public function testRequiredAndTypedValuesFailBeforeTheWriter():void{foreach(['missing','empty','long','decimal']as $case){$sent=[];$logs=[];$s=$this->service('create',RuntimePurchaseItemAuditTest::body('create'),$sent,$logs);$r=RuntimePurchaseItemAuditTest::row();unset($r['item_proc_compra_id']);if($case==='missing')unset($r['descricao']);if($case==='empty')$r['descricao']='';if($case==='long')$r['descricao']=str_repeat('X',101);if($case==='decimal')$r['qt_comprada']='1,23';try{$this->invoke($s,'create',$r);self::fail($case);}catch(RuntimeHttpException $e){self::assertSame(422,$e->getStatusCode());}self::assertSame([],$sent);}}
 public function testGetHasFullFiftyFieldsNormalizedIdentityAndParent():void{$sent=[];$logs=[];$s=$this->service('get',['success'=>true,'data'=>RuntimePurchaseItemAuditTest::data()],$sent,$logs);$out=$this->invoke($s,'get',['item_proc_compra_id'=>'11'],'11');self::assertCount(50,$out);self::assertSame(11,$sent[0]['id']);self::assertArrayNotHasKey('item_proc_compra_id',$sent[0]);foreach(['stamp','parent','key','success']as $case){$d=RuntimePurchaseItemAuditTest::data();if($case==='stamp')unset($d['row_stamp']);if($case==='parent')$d['proc_compra_id']=18;if($case==='key')$d['item_proc_compra_id']=12;$sent=[];$logs=[];$s=$this->service('get',['success'=>$case!=='success','data'=>$d],$sent,$logs);try{$this->invoke($s,'get',[],11);self::fail($case);}catch(RuntimeHttpException $e){self::assertSame(502,$e->getStatusCode());}}}
 public function testCommittedForeignDtoDoesNotReplaceTheSubmittedIdentity():void{$body=RuntimePurchaseItemAuditTest::body();$body['data']['item_proc_compra_id']=12;$sent=[];$logs=[];$s=$this->service('update',$body,$sent,$logs);$out=$this->invoke($s,'update',RuntimePurchaseItemAuditTest::data(),11);self::assertSame(11,$out['item_proc_compra_id']);self::assertCount(1,$sent);self::assertSame('warning',$out['effects'][0]['type']);}
 public function testUncommittedWritesNeverImportImagesOrRetry():void{foreach(['create','update','delete']as $op){$body=RuntimePurchaseItemAuditTest::body($op);$body['committed']=false;$sent=[];$logs=[];$s=$this->service($op,$body,$sent,$logs);$r=RuntimePurchaseItemAuditTest::data();if($op==='create')unset($r['item_proc_compra_id'],$r['row_stamp']);try{$this->invoke($s,$op,$r,$op==='create'?null:11);self::fail($op);}catch(RuntimeHttpException $e){self::assertSame(502,$e->getStatusCode());}self::assertCount(1,$sent);foreach($logs as $log)self::assertFalse($log->getMetadata()['audit']['available']??false);}}
 public function testIdentityParentAndProjectionsCannotBecomeEditableThroughMapping():void{$sent=[];$logs=[];$s=$this->service('create',RuntimePurchaseItemAuditTest::body('create'),$sent,$logs,false,true);$r=RuntimePurchaseItemAuditTest::data();unset($r['item_proc_compra_id'],$r['row_stamp']);$this->invoke($s,'create',$r);foreach(['proc_compra_id','qt_alocada','qt_saldo','calc_gm']as $key)self::assertArrayNotHasKey($key,$sent[0]['values']);}
}
